schema:
CREATE INDEX idx_receipts_method ON receipts(payment_method);

CREATE INDEX idx_ticket_lines_ticket ON ticket_lines(ticket_id);

CREATE INDEX idx_tickets_site_date ON service_tickets(site_id, opened_at);

CREATE TABLE customers (customer_id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL, loyalty_level TEXT NOT NULL, joined_on TEXT NOT NULL);

CREATE TABLE offerings (offering_id INTEGER PRIMARY KEY, offering_name TEXT NOT NULL, category TEXT NOT NULL, unit_price REAL NOT NULL, vegetarian INTEGER NOT NULL, active INTEGER NOT NULL);

CREATE TABLE receipts (receipt_id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL, issued_at TEXT NOT NULL, payment_method TEXT NOT NULL, subtotal REAL NOT NULL, tip_amount REAL NOT NULL, paid_amount REAL NOT NULL, FOREIGN KEY (ticket_id) REFERENCES service_tickets(ticket_id));

CREATE TABLE service_sites (site_id INTEGER PRIMARY KEY, site_name TEXT NOT NULL, city TEXT NOT NULL, neighborhood TEXT NOT NULL, seating_capacity INTEGER NOT NULL, opening_year INTEGER NOT NULL);

CREATE TABLE service_tickets (ticket_id INTEGER PRIMARY KEY, site_id INTEGER NOT NULL, customer_id INTEGER NOT NULL, opened_at TEXT NOT NULL, channel TEXT NOT NULL, status TEXT NOT NULL, table_code TEXT, FOREIGN KEY (site_id) REFERENCES service_sites(site_id), FOREIGN KEY (customer_id) REFERENCES customers(customer_id));

CREATE TABLE ticket_lines (line_id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL, offering_id INTEGER NOT NULL, quantity INTEGER NOT NULL, unit_price REAL NOT NULL, FOREIGN KEY (ticket_id) REFERENCES service_tickets(ticket_id), FOREIGN KEY (offering_id) REFERENCES offerings(offering_id));

CREATE INDEX idx_auditoriums_venue ON auditoriums(venue_id);

CREATE INDEX idx_reservations_session ON reservations(session_id);

CREATE INDEX idx_session_artists_artist ON session_artists(artist_id);

CREATE INDEX idx_sessions_date ON sessions(starts_at);

CREATE INDEX idx_sessions_production ON sessions(production_id);

CREATE TABLE artists (
    artist_id INTEGER PRIMARY KEY,
    stage_name TEXT NOT NULL,
    specialty TEXT NOT NULL,
    home_city TEXT NOT NULL
);

CREATE TABLE auditoriums (
    auditorium_id INTEGER PRIMARY KEY,
    venue_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    seat_count INTEGER NOT NULL,
    accessibility_level TEXT NOT NULL,
    FOREIGN KEY (venue_id) REFERENCES venues(venue_id)
);

CREATE TABLE productions (
    production_id INTEGER PRIMARY KEY,
    title TEXT NOT NULL,
    category TEXT NOT NULL,
    company TEXT NOT NULL,
    duration_minutes INTEGER NOT NULL,
    minimum_age INTEGER NOT NULL
);

CREATE TABLE reservations (
    reservation_id INTEGER PRIMARY KEY,
    session_id INTEGER NOT NULL,
    customer_name TEXT NOT NULL,
    seats_reserved INTEGER NOT NULL,
    amount_paid REAL NOT NULL,
    booked_on TEXT NOT NULL,
    payment_status TEXT NOT NULL,
    FOREIGN KEY (session_id) REFERENCES sessions(session_id)
);

CREATE TABLE session_artists (
    session_id INTEGER NOT NULL,
    artist_id INTEGER NOT NULL,
    role_name TEXT NOT NULL,
    billing_order INTEGER NOT NULL,
    PRIMARY KEY (session_id, artist_id),
    FOREIGN KEY (session_id) REFERENCES sessions(session_id),
    FOREIGN KEY (artist_id) REFERENCES artists(artist_id)
);

CREATE TABLE sessions (
    session_id INTEGER PRIMARY KEY,
    production_id INTEGER NOT NULL,
    auditorium_id INTEGER NOT NULL,
    starts_at TEXT NOT NULL,
    base_price REAL NOT NULL,
    status TEXT NOT NULL,
    FOREIGN KEY (production_id) REFERENCES productions(production_id),
    FOREIGN KEY (auditorium_id) REFERENCES auditoriums(auditorium_id)
);

CREATE TABLE venues (
    venue_id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    city TEXT NOT NULL,
    address TEXT NOT NULL,
    opened_year INTEGER NOT NULL
);

CREATE INDEX idx_event_organizer ON conference_event (organizer_id);

CREATE INDEX idx_registration_attendee ON event_registration (attendee_id);

CREATE INDEX idx_registration_event ON event_registration (event_id);

CREATE INDEX idx_session_event ON event_session (event_id);

CREATE INDEX idx_session_room ON event_session (room_id);

CREATE TABLE attendee (attendee_id INTEGER PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT NOT NULL, company_name TEXT NOT NULL, job_title TEXT NOT NULL, country TEXT NOT NULL);

CREATE TABLE conference_event (event_id INTEGER PRIMARY KEY, organizer_id INTEGER NOT NULL, event_title TEXT NOT NULL, event_category TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, expected_attendance INTEGER NOT NULL, status TEXT NOT NULL, FOREIGN KEY (organizer_id) REFERENCES organizer (organizer_id));

CREATE TABLE event_registration (registration_id INTEGER PRIMARY KEY, event_id INTEGER NOT NULL, attendee_id INTEGER NOT NULL, registered_at TEXT NOT NULL, ticket_type TEXT NOT NULL, payment_status TEXT NOT NULL, check_in_status TEXT NOT NULL, FOREIGN KEY (event_id) REFERENCES conference_event (event_id), FOREIGN KEY (attendee_id) REFERENCES attendee (attendee_id));

CREATE TABLE event_session (session_id INTEGER PRIMARY KEY, event_id INTEGER NOT NULL, room_id INTEGER NOT NULL, session_title TEXT NOT NULL, session_format TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, speaker_name TEXT NOT NULL, FOREIGN KEY (event_id) REFERENCES conference_event (event_id), FOREIGN KEY (room_id) REFERENCES venue_room (room_id));

CREATE TABLE organizer (organizer_id INTEGER PRIMARY KEY, organization_name TEXT NOT NULL, contact_name TEXT NOT NULL, contact_email TEXT NOT NULL, sector TEXT NOT NULL, city TEXT NOT NULL);

CREATE TABLE venue_room (room_id INTEGER PRIMARY KEY, room_name TEXT NOT NULL, floor_number INTEGER NOT NULL, capacity INTEGER NOT NULL, room_type TEXT NOT NULL, accessibility_level TEXT NOT NULL);

CREATE INDEX idx_order_entries_title ON order_entries(title_id);

CREATE INDEX idx_orders_date ON orders(ordered_on);

CREATE INDEX idx_orders_patron ON orders(patron_id);

CREATE INDEX idx_titles_genre ON titles(genre);

CREATE INDEX idx_titles_writer ON titles(writer_id);

CREATE TABLE order_entries (
    entry_id INTEGER PRIMARY KEY,
    order_id INTEGER NOT NULL,
    title_id INTEGER NOT NULL,
    quantity INTEGER NOT NULL,
    unit_price REAL NOT NULL,
    FOREIGN KEY (order_id) REFERENCES orders(order_id),
    FOREIGN KEY (title_id) REFERENCES titles(title_id)
);

CREATE TABLE orders (
    order_id INTEGER PRIMARY KEY,
    patron_id INTEGER NOT NULL,
    ordered_on TEXT NOT NULL,
    sales_channel TEXT NOT NULL,
    payment_method TEXT NOT NULL,
    order_status TEXT NOT NULL,
    FOREIGN KEY (patron_id) REFERENCES patrons(patron_id)
);

CREATE TABLE patrons (
    patron_id INTEGER PRIMARY KEY,
    full_name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    neighborhood TEXT NOT NULL,
    joined_on TEXT NOT NULL
);

CREATE TABLE titles (
    title_id INTEGER PRIMARY KEY,
    writer_id INTEGER NOT NULL,
    title_name TEXT NOT NULL,
    genre TEXT NOT NULL,
    published_year INTEGER NOT NULL,
    unit_price REAL NOT NULL,
    stock_count INTEGER NOT NULL,
    FOREIGN KEY (writer_id) REFERENCES writers(writer_id)
);

CREATE TABLE writers (
    writer_id INTEGER PRIMARY KEY,
    full_name TEXT NOT NULL,
    country TEXT NOT NULL,
    birth_year INTEGER,
    specialty TEXT NOT NULL
);

CREATE INDEX idx_charge_status ON charge(payment_status);

CREATE INDEX idx_cycle_hub ON cycle(hub_id);

CREATE INDEX idx_hire_rider ON hire(rider_id);

CREATE INDEX idx_hire_started_at ON hire(started_at);

CREATE TABLE charge (charge_id INTEGER PRIMARY KEY, hire_id INTEGER NOT NULL, charged_at TEXT NOT NULL, amount_cents INTEGER NOT NULL, payment_method TEXT NOT NULL, payment_status TEXT NOT NULL, FOREIGN KEY (hire_id) REFERENCES hire(hire_id));

CREATE TABLE cycle (cycle_id INTEGER PRIMARY KEY, serial_code TEXT NOT NULL UNIQUE, cycle_type TEXT NOT NULL, hub_id INTEGER NOT NULL, status TEXT NOT NULL, acquired_on TEXT NOT NULL, FOREIGN KEY (hub_id) REFERENCES hub(hub_id));

CREATE TABLE hire (hire_id INTEGER PRIMARY KEY, rider_id INTEGER NOT NULL, cycle_id INTEGER NOT NULL, start_hub_id INTEGER NOT NULL, end_hub_id INTEGER NOT NULL, started_at TEXT NOT NULL, ended_at TEXT NOT NULL, distance_km REAL NOT NULL, fare_cents INTEGER NOT NULL, FOREIGN KEY (rider_id) REFERENCES rider(rider_id), FOREIGN KEY (cycle_id) REFERENCES cycle(cycle_id), FOREIGN KEY (start_hub_id) REFERENCES hub(hub_id), FOREIGN KEY (end_hub_id) REFERENCES hub(hub_id));

CREATE TABLE hub (hub_id INTEGER PRIMARY KEY, hub_name TEXT NOT NULL, district TEXT NOT NULL, capacity INTEGER NOT NULL, opened_on TEXT NOT NULL);

CREATE TABLE rider (rider_id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, joined_on TEXT NOT NULL, membership TEXT NOT NULL, home_area TEXT NOT NULL);

CREATE INDEX idx_registration_member ON session_registration(member_id);

CREATE INDEX idx_session_date ON training_session(session_date);

CREATE INDEX idx_team_sport ON team(sport_id);

CREATE TABLE coach (coach_id INTEGER PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, specialty TEXT NOT NULL, hire_year INTEGER NOT NULL);

CREATE TABLE facility (facility_id INTEGER PRIMARY KEY, facility_name TEXT NOT NULL UNIQUE, neighborhood TEXT NOT NULL, capacity INTEGER NOT NULL, hourly_rate REAL NOT NULL);

CREATE TABLE member (member_id INTEGER PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, birth_year INTEGER NOT NULL, membership_type TEXT NOT NULL, join_date TEXT NOT NULL, active_flag INTEGER NOT NULL);

CREATE TABLE session_registration (session_id INTEGER NOT NULL, member_id INTEGER NOT NULL, registration_status TEXT NOT NULL, attended_flag INTEGER NOT NULL, rating INTEGER, PRIMARY KEY (session_id, member_id), FOREIGN KEY (session_id) REFERENCES training_session(session_id), FOREIGN KEY (member_id) REFERENCES member(member_id));

CREATE TABLE sport (sport_id INTEGER PRIMARY KEY, sport_name TEXT NOT NULL UNIQUE, indoor_flag INTEGER NOT NULL, difficulty_level INTEGER NOT NULL);

CREATE TABLE team (team_id INTEGER PRIMARY KEY, team_name TEXT NOT NULL UNIQUE, sport_id INTEGER NOT NULL, coach_id INTEGER NOT NULL, captain_member_id INTEGER NOT NULL, level_name TEXT NOT NULL, FOREIGN KEY (sport_id) REFERENCES sport(sport_id), FOREIGN KEY (coach_id) REFERENCES coach(coach_id), FOREIGN KEY (captain_member_id) REFERENCES member(member_id));

CREATE TABLE training_session (session_id INTEGER PRIMARY KEY, team_id INTEGER NOT NULL, coach_id INTEGER NOT NULL, facility_id INTEGER NOT NULL, session_date TEXT NOT NULL, start_time TEXT NOT NULL, duration_minutes INTEGER NOT NULL, session_status TEXT NOT NULL, FOREIGN KEY (team_id) REFERENCES team(team_id), FOREIGN KEY (coach_id) REFERENCES coach(coach_id), FOREIGN KEY (facility_id) REFERENCES facility(facility_id));

CREATE INDEX idx_contract_slot ON mooring_contract(slot_id);

CREATE INDEX idx_contract_vessel ON mooring_contract(vessel_id);

CREATE INDEX idx_pier_site ON pier_slot(site_id);

CREATE INDEX idx_work_contract ON work_order(contract_id);

CREATE TABLE marina_site (site_id INTEGER PRIMARY KEY, dataset_key TEXT NOT NULL, site_name TEXT NOT NULL, town TEXT NOT NULL, region TEXT NOT NULL, capacity INTEGER NOT NULL, opening_month INTEGER NOT NULL, annual_fee REAL NOT NULL);

CREATE TABLE mooring_contract (contract_id INTEGER PRIMARY KEY, dataset_key TEXT NOT NULL, slot_id INTEGER NOT NULL, vessel_id INTEGER NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, contract_status TEXT NOT NULL, billing_cycle TEXT NOT NULL, agreed_rate REAL NOT NULL, FOREIGN KEY (slot_id) REFERENCES pier_slot(slot_id), FOREIGN KEY (vessel_id) REFERENCES vessel(vessel_id));

CREATE TABLE pier_slot (slot_id INTEGER PRIMARY KEY, dataset_key TEXT NOT NULL, site_id INTEGER NOT NULL, pontoon_code TEXT NOT NULL, slot_number INTEGER NOT NULL, length_m REAL NOT NULL, width_m REAL NOT NULL, water_depth_m REAL NOT NULL, monthly_rate REAL NOT NULL, FOREIGN KEY (site_id) REFERENCES marina_site(site_id));

CREATE TABLE vessel (vessel_id INTEGER PRIMARY KEY, dataset_key TEXT NOT NULL, registration_code TEXT NOT NULL UNIQUE, vessel_name TEXT NOT NULL, vessel_type TEXT NOT NULL, owner_name TEXT NOT NULL, length_m REAL NOT NULL, draft_m REAL NOT NULL, home_town TEXT NOT NULL, built_year INTEGER NOT NULL);

CREATE TABLE work_order (work_order_id INTEGER PRIMARY KEY, dataset_key TEXT NOT NULL, contract_id INTEGER NOT NULL, opened_date TEXT NOT NULL, completed_date TEXT, category TEXT NOT NULL, description TEXT NOT NULL, provider_name TEXT NOT NULL, amount REAL NOT NULL, work_status TEXT NOT NULL, FOREIGN KEY (contract_id) REFERENCES mooring_contract(contract_id));

CREATE INDEX idx_order_line_order ON sales_order_line(order_id);

CREATE INDEX idx_order_line_variety ON sales_order_line(variety_id);

CREATE INDEX idx_sales_order_customer ON sales_order(customer_id);

CREATE INDEX idx_stock_lot_section ON stock_lot(section_id);

CREATE INDEX idx_stock_lot_variety ON stock_lot(variety_id);

CREATE TABLE customer (customer_id INTEGER PRIMARY KEY, customer_name TEXT NOT NULL, customer_type TEXT NOT NULL, city TEXT NOT NULL, email TEXT NOT NULL, loyalty_level TEXT NOT NULL);

CREATE TABLE nursery_section (section_id INTEGER PRIMARY KEY, section_name TEXT NOT NULL, location_type TEXT NOT NULL, climate_control TEXT NOT NULL, capacity_units INTEGER NOT NULL);

CREATE TABLE plant_variety (variety_id INTEGER PRIMARY KEY, botanical_name TEXT NOT NULL, common_name TEXT NOT NULL, plant_type TEXT NOT NULL, sun_exposure TEXT NOT NULL, hardiness_zone TEXT NOT NULL, unit_price REAL NOT NULL);

CREATE TABLE sales_order (order_id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL, order_date TEXT NOT NULL, delivery_date TEXT, channel TEXT NOT NULL, order_status TEXT NOT NULL, FOREIGN KEY (customer_id) REFERENCES customer(customer_id));

CREATE TABLE sales_order_line (line_id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL, variety_id INTEGER NOT NULL, lot_id INTEGER NOT NULL, quantity INTEGER NOT NULL, unit_price REAL NOT NULL, discount_rate REAL NOT NULL, FOREIGN KEY (order_id) REFERENCES sales_order(order_id), FOREIGN KEY (variety_id) REFERENCES plant_variety(variety_id), FOREIGN KEY (lot_id) REFERENCES stock_lot(lot_id));

CREATE TABLE stock_lot (lot_id INTEGER PRIMARY KEY, variety_id INTEGER NOT NULL, supplier_id INTEGER NOT NULL, section_id INTEGER NOT NULL, received_date TEXT NOT NULL, quantity INTEGER NOT NULL, unit_cost REAL NOT NULL, status TEXT NOT NULL, FOREIGN KEY (variety_id) REFERENCES plant_variety(variety_id), FOREIGN KEY (supplier_id) REFERENCES supplier(supplier_id), FOREIGN KEY (section_id) REFERENCES nursery_section(section_id));

CREATE TABLE supplier (supplier_id INTEGER PRIMARY KEY, company_name TEXT NOT NULL, city TEXT NOT NULL, region TEXT NOT NULL, contact_email TEXT NOT NULL, organic_certified INTEGER NOT NULL);

CREATE INDEX idx_order_lines_order ON order_lines(order_id);

CREATE INDEX idx_order_lines_product ON order_lines(product_id);

CREATE INDEX idx_orders_customer ON market_orders(customer_id);

CREATE INDEX idx_orders_market_day ON market_orders(market_day_id);

CREATE INDEX idx_products_stall ON products(stall_id);

CREATE INDEX idx_stalls_vendor ON stalls(vendor_id);

CREATE TABLE customers (
    customer_id INTEGER PRIMARY KEY,
    customer_name TEXT NOT NULL,
    neighborhood TEXT NOT NULL,
    loyalty_level TEXT NOT NULL,
    joined_on TEXT NOT NULL
);

CREATE TABLE market_days (
    market_day_id INTEGER PRIMARY KEY,
    market_code TEXT NOT NULL,
    market_date TEXT NOT NULL,
    neighborhood TEXT NOT NULL,
    opening_note TEXT NOT NULL
);

CREATE TABLE market_orders (
    order_id INTEGER PRIMARY KEY,
    market_day_id INTEGER NOT NULL,
    customer_id INTEGER NOT NULL,
    stall_id INTEGER NOT NULL,
    ordered_at TEXT NOT NULL,
    payment_status TEXT NOT NULL,
    FOREIGN KEY (market_day_id) REFERENCES market_days(market_day_id),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (stall_id) REFERENCES stalls(stall_id)
);

CREATE TABLE order_lines (
    order_line_id INTEGER PRIMARY KEY,
    order_id INTEGER NOT NULL,
    product_id INTEGER NOT NULL,
    quantity INTEGER NOT NULL,
    unit_price REAL NOT NULL,
    FOREIGN KEY (order_id) REFERENCES market_orders(order_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

CREATE TABLE products (
    product_id INTEGER PRIMARY KEY,
    stall_id INTEGER NOT NULL,
    product_name TEXT NOT NULL,
    category TEXT NOT NULL,
    unit TEXT NOT NULL,
    unit_price REAL NOT NULL,
    seasonal INTEGER NOT NULL CHECK (seasonal IN (0,1)),
    FOREIGN KEY (stall_id) REFERENCES stalls(stall_id)
);

CREATE TABLE stalls (
    stall_id INTEGER PRIMARY KEY,
    vendor_id INTEGER NOT NULL,
    stall_label TEXT NOT NULL,
    aisle_name TEXT NOT NULL,
    payment_method TEXT NOT NULL,
    FOREIGN KEY (vendor_id) REFERENCES vendors(vendor_id)
);

CREATE TABLE vendors (
    vendor_id INTEGER PRIMARY KEY,
    vendor_name TEXT NOT NULL,
    specialty TEXT NOT NULL,
    town TEXT NOT NULL,
    organic_certified INTEGER NOT NULL CHECK (organic_certified IN (0,1))
);

CREATE INDEX idx_auditorium_venue ON auditorium(venue_id);

CREATE INDEX idx_reservation_patron ON reservation(patron_id);

CREATE INDEX idx_reservation_showtime ON reservation(showtime_id);

CREATE INDEX idx_showtime_auditorium ON showtime(auditorium_id);

CREATE INDEX idx_showtime_production ON showtime(production_id);

CREATE TABLE auditorium (auditorium_id INTEGER PRIMARY KEY, venue_id INTEGER NOT NULL, auditorium_name TEXT NOT NULL, seat_count INTEGER NOT NULL, floor_label TEXT NOT NULL, accessibility_level TEXT NOT NULL, FOREIGN KEY (venue_id) REFERENCES venue(venue_id));

CREATE TABLE patron (patron_id INTEGER PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, joined_on TEXT NOT NULL, membership_level TEXT NOT NULL);

CREATE TABLE production (production_id INTEGER PRIMARY KEY, title TEXT NOT NULL, genre TEXT NOT NULL, company_name TEXT NOT NULL, duration_minutes INTEGER NOT NULL, age_rating TEXT NOT NULL);

CREATE TABLE reservation (reservation_id INTEGER PRIMARY KEY, patron_id INTEGER NOT NULL, showtime_id INTEGER NOT NULL, reserved_on TEXT NOT NULL, seats_booked INTEGER NOT NULL, payment_status TEXT NOT NULL, booking_channel TEXT NOT NULL, FOREIGN KEY (patron_id) REFERENCES patron(patron_id), FOREIGN KEY (showtime_id) REFERENCES showtime(showtime_id));

CREATE TABLE showtime (showtime_id INTEGER PRIMARY KEY, production_id INTEGER NOT NULL, auditorium_id INTEGER NOT NULL, starts_at TEXT NOT NULL, ticket_price REAL NOT NULL, format_label TEXT NOT NULL, show_status TEXT NOT NULL, FOREIGN KEY (production_id) REFERENCES production(production_id), FOREIGN KEY (auditorium_id) REFERENCES auditorium(auditorium_id));

CREATE TABLE venue (venue_id INTEGER PRIMARY KEY, venue_name TEXT NOT NULL, city TEXT NOT NULL, district TEXT NOT NULL, opened_year INTEGER NOT NULL, venue_type TEXT NOT NULL);

CREATE INDEX idx_garage_operator ON garage(operator_id);

CREATE INDEX idx_line_operator ON bus_line(operator_id);

CREATE INDEX idx_line_stop_line ON line_stop(line_id);

CREATE INDEX idx_line_stop_stop ON line_stop(stop_id);

CREATE INDEX idx_trip_date ON scheduled_trip(service_date);

CREATE INDEX idx_vehicle_garage ON bus_vehicle(garage_id);

CREATE TABLE bus_line (
    id INTEGER PRIMARY KEY,
    operator_id INTEGER NOT NULL,
    code TEXT NOT NULL UNIQUE,
    label TEXT NOT NULL,
    mode TEXT NOT NULL,
    night_service INTEGER NOT NULL,
    FOREIGN KEY (operator_id) REFERENCES operator_company(id)
);

CREATE TABLE bus_vehicle (
    id INTEGER PRIMARY KEY,
    garage_id INTEGER NOT NULL,
    fleet_number TEXT NOT NULL UNIQUE,
    model TEXT NOT NULL,
    capacity INTEGER NOT NULL,
    commissioned_year INTEGER NOT NULL,
    status TEXT NOT NULL,
    FOREIGN KEY (garage_id) REFERENCES garage(id)
);

CREATE TABLE garage (
    id INTEGER PRIMARY KEY,
    operator_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    city TEXT NOT NULL,
    capacity INTEGER NOT NULL,
    FOREIGN KEY (operator_id) REFERENCES operator_company(id)
);

CREATE TABLE line_stop (
    id INTEGER PRIMARY KEY,
    line_id INTEGER NOT NULL,
    stop_id INTEGER NOT NULL,
    stop_order INTEGER NOT NULL,
    minutes_from_start INTEGER NOT NULL,
    FOREIGN KEY (line_id) REFERENCES bus_line(id),
    FOREIGN KEY (stop_id) REFERENCES stop_point(id),
    UNIQUE (line_id, stop_order)
);

CREATE TABLE operator_company (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    city TEXT NOT NULL,
    license_code TEXT NOT NULL UNIQUE
);

CREATE TABLE scheduled_trip (
    id INTEGER PRIMARY KEY,
    line_id INTEGER NOT NULL,
    vehicle_id INTEGER NOT NULL,
    service_date TEXT NOT NULL,
    departure_time TEXT NOT NULL,
    trip_status TEXT NOT NULL,
    FOREIGN KEY (line_id) REFERENCES bus_line(id),
    FOREIGN KEY (vehicle_id) REFERENCES bus_vehicle(id)
);

CREATE TABLE stop_point (
    id INTEGER PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    city TEXT NOT NULL,
    zone INTEGER NOT NULL
);
